interface ArtifactViewerProps {
  evidence: EvidenceDetailEntry;
}

/**
 * Renders a custom artifact.
 *
 * The document is author-supplied HTML, so it is mounted in a sandboxed iframe
 * with no `allow-same-origin`. That is the load-bearing part: with same-origin
 * the frame could reach this page's cookies and localStorage, which is the
 * player's session. `allow-scripts` stays on because an artifact is allowed to
 * script itself, just not to touch the host document.
 */
const ArtifactViewer: FC = ({ evidence }) => {
  const { t } = useTranslation();

  const srcDoc = useMemo(() => buildArtifactDocument(evidence.content_payload), [evidence.content_payload]);

  if (srcDoc === null) {
    return (



          {t('pages.gameRoom.evidence.viewers.artifact.empty', 'This artifact has no content yet.')}


    );
  }

  return (






  );
};

/**
 * Composes the artifact into a standalone document.
 *
 * The server already ran the markup and the stylesheet through its sanitizer
 * with a reject-don't-rewrite CSS policy, so anything that arrived here has
 * been checked. The iframe boundary is what makes that check meaningful at
 * runtime.
 */
function buildArtifactDocument(payload: unknown): string | null {
  if (typeof payload !== 'object' || payload === null) {
    return null;
  }

  const candidate = payload as Partial;

  if (candidate.kind !== 'html' || typeof candidate.html !== 'string' || candidate.html.trim() === '') {
    return null;
  }

  const css = typeof candidate.css === 'string' ? candidate.css : '';

  return [
    '',
    '',
    '
',
    '',
    '',
    // The artifact stylesheet is injected into its own document rather than
    // adopted into this page, so it cannot reach the surrounding UI.
    ``,
    '',
    '',
    candidate.html,
    '',
    '',
  ].join('');
}

export default ArtifactViewer;

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import type { EvidenceDetailEntry } from '@/types/evidence';
import ViewersContainer from './ViewersContainer';
import './MediaViewer.css';

interface MediaViewerProps {
  evidence: EvidenceDetailEntry;
}

/**
 * Renders the single file a media evidence carries.
 *
 * The asset is read from the server's `media` lookup rather than from a pair of
 * nullable url columns, so a media evidence always has a declared kind and the
 * viewer never has to infer one from the evidence type.
 */
/**
 * Intrinsic size of a loaded image, tagged with the url it describes.
 *
 * The tag replaces a reset inside the effect: a stale measurement is detected by
 * comparison, so switching files never has to synchronously clear state first.
 */
type ImageMeasurement = { url: string; width: number; height: number };

const MediaViewer: React.FC = ({ evidence }) => {
  const { t } = useTranslation();
  const [measurement, setMeasurement] = useState(null);
  const [loadedUrl, setLoadedUrl] = useState(null);

  const image = evidence.media.image;
  const audio = evidence.media.audio;
  const asset = image ?? audio;
  const mediaUrl = asset?.url ?? null;

  useEffect(() => {
    if (!image?.url) return;

    let isMounted = true;

    const img = new Image();
    img.src = image.url;

    img.onload = () => {
      if (isMounted) {
        setMeasurement({ url: image.url, width: img.naturalWidth, height: img.naturalHeight });
        setLoadedUrl(image.url);
      }
    };
    img.onerror = () => {
      if (isMounted) {
        // A broken image still gets a box, so the plaque below it stays readable
        // instead of collapsing the layout.
        setMeasurement({ url: image.url, width: 16, height: 9 });
        setLoadedUrl(image.url);
      }
    };

    return () => {
      isMounted = false;
    };
  }, [image?.url]);

  const isImageLoaded = loadedUrl === image?.url;
  const dimensions = measurement?.url === image?.url ? measurement : null;

  if (!mediaUrl) {
    return (



          {t('pages.gameRoom.evidence.viewers.media.noMediaFound', 'No media attached to this evidence.')}


    );
