export const createAdminCharacter = (fd: FormData) => adminRequest('/characters', { method: 'POST', body: fd });
export const updateAdminCharacter = (id: number, fd: FormData) => { fd.append('_method', 'PUT'); return adminRequest(`/characters/${id}`, { method: 'POST', body: fd }); };
export const deleteAdminCharacter = (id: number) => adminRequest(`/characters/${id}`, { method: 'DELETE' });

import { type Result, success, failure } from '../utils/Result';
import type { GameCase, GameRoom, User } from '../types';
import type { EvidenceDetailEntry } from '../types/evidence';
import { getToken, logout } from './auth';

const API_BASE_URL = import.meta.env.VITE_API_URL ?? 'http://localhost:8000/api';

const handleUnauthorized = () => {
  logout();
  window.dispatchEvent(new CustomEvent('auth:unauthorized'));
};

export const fetchCases = async (): Promise<Result<{ cases: GameCase[], user: User }>> => {
  try {
    const response = await fetch(`${API_BASE_URL}/cases`, {
      headers: {
        'Accept': 'application/json',
        'Authorization': `Bearer ${getToken()}`
      }
    });

    if (!response.ok) {
      if (response.status === 401) {
        handleUnauthorized();
        return failure('Session expired.');
      }
      return failure(`Server responded with status: ${response.status}`);
    }

    const data = await response.json();
    // Return both pieces of data
    return success({ cases: data.cases, user: data.user });
  } catch (error) {
    return failure(error instanceof Error ? error.message : 'Network error');
  }
};

export const createRoom = async (caseId: number): Promise<Result> => {
  try {
    const response = await fetch(`${API_BASE_URL}/rooms`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'Authorization': `Bearer ${getToken()}`
      },
      body: JSON.stringify({ case_id: caseId }),
    });

    if (!response.ok) {
      if (response.status === 401) {
        handleUnauthorized();
        return failure('Session expired.');
      }
      const data = await response.json();
      return failure(data.message || 'Failed to create session.');
    }

    const data = await response.json();
    return success(data.room);
  } catch (error) {
    return failure(error instanceof Error ? error.message : 'Network error');
  }
};

