/**
 * Fetches the full body of a single evidence.
 *
 * The board listing ships no content, so opening a file is the only time the
 * payload is requested. The server answers 404 both for evidence that does not
 * exist and for evidence this room has not unlocked, so a failure here is
 * reported as generic on purpose rather than distinguishing the two.
 */
export const fetchEvidenceDetail = async (
  roomId: number,
  evidenceId: number
): Promise<Result> => {
  try {
    const response = await fetch(`${API_BASE_URL}/rooms/${roomId}/evidences/${evidenceId}`, {
      method: 'GET',
      headers: {
        'Accept': 'application/json',
        'Authorization': `Bearer ${getToken()}`
      }
    });

    if (!response.ok) {
      if (response.status === 401) {
        handleUnauthorized();
        return failure('Session expired.');
      }
      const data = await response.json().catch(() => null);
      return failure(data?.message || 'This file could not be opened.');
    }

    const data = await response.json();
    return success(data.evidence as EvidenceDetailEntry);
  } catch (error) {
    return failure(error instanceof Error ? error.message : 'Network error');
  }
};

export const lockVote = async (roomId: number, questionId: number, choiceId: number): Promise<Result> => {
  try {
    const response = await fetch(`${API_BASE_URL}/rooms/${roomId}/questions/${questionId}/vote`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'Authorization': `Bearer ${getToken()}`
      },
      body: JSON.stringify({ choice_id: choiceId }),
    });

    if (!response.ok) {
      if (response.status === 401) handleUnauthorized();
      return failure('Failed to lock vote.');
    }
    return success(await response.json());
  } catch (error) {
    return failure(error instanceof Error ? error.message : 'Network error');
  }
};

export const submitAssessment = async (roomId: number): Promise<Result<{ status: string; message: string; }, { title: string, message: string }>> => {
  try {
    const response = await fetch(`${API_BASE_URL}/rooms/${roomId}/submit`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'Authorization': `Bearer ${getToken()}`
      }
    });

    if (!response.ok) {
      if (response.status === 401) handleUnauthorized();
      const data = await response.json().catch(() => null);
      return failure({
        title: data?.error || 'Theory Rejected',
        message: data?.message || 'Failed to submit theory.'
      });
    }
    return success(await response.json());
  } catch (error) {
    return failure({ title: 'Network Error', message: error instanceof Error ? error.message : 'Unknown error' });
  }
};

